// ReproduceRailSubmenuBug.js
import React, { useState } from 'react';
import ReactDOM from 'react-dom';
import 'carbon-components/css/carbon-components.min.css';
import {
  SideNav,
  SideNavItems,
  SideNavMenu,
  SideNavMenuItem,
  Header,
  HeaderName,
  HeaderMenuButton,
} from 'carbon-components-react';
import { Menu20, Dashboard20, Apps20 } from '@carbon/icons-react';

function DemoShell() {
  // Control rail mode and expansion
  const [isRailMode, setRailMode] = useState(true);
  const [isExpanded, setExpanded] = useState(true);

  const handleToggleRail = () => {
    setRailMode(prev => !prev);
    // whenever you switch into rail mode, collapse the nav
    setExpanded(false);
  };

  const handleToggleExpand = () => {
    setExpanded(prev => !prev);
  };

  return (
    <div style={{ display: 'flex', height: '100vh' }}>
      {/* Top header with hamburger toggle */}
      <Header aria-label="IBM Product">
        <HeaderMenuButton
          aria-label="Toggle side nav"
          onClick={handleToggleExpand}
        />
        <HeaderName href="#" prefix="IBM">
          Product
        </HeaderName>
      </Header>

      {/* Side navigation (rail) */}
      <SideNav
        isRail={isRailMode}
        expanded={isExpanded}
        onToggle={(evt, value) => setExpanded(value)}
        aria-label="Side navigation">
        <SideNavItems>
          {/* Simple link for reference */}
          <SideNavMenu renderIcon={Menu20} title="Dashboard">
            <SideNavMenuItem href="#" isActive>
              Overview
            </SideNavMenuItem>
            <SideNavMenuItem href="#">
              Details
            </SideNavMenuItem>
          </SideNavMenu>

          {/* Submenu used to reproduce the bug */}
          <SideNavMenu renderIcon={Apps20} title="Applications" defaultExpanded>
            <SideNavMenuItem href="#" isActive>
              App One
            </SideNavMenuItem>
            <SideNavMenuItem href="#">
              App Two
            </SideNavMenuItem>
            <SideNavMenuItem href="#">
              App Three
            </SideNavMenuItem>
          </SideNavMenu>
        </SideNavItems>
      </SideNav>

      {/* Controls to reproduce the bug scenario */}
      <div style={{ margin: '1rem' }}>
        <button onClick={handleToggleRail} style={{ display: 'block', margin: '0 0 1rem 0' }}>
          {isRailMode ? 'Disable Rail Mode' : 'Enable Rail Mode'}
        </button>
        <button onClick={handleToggleExpand}>
          {isExpanded ? 'Collapse Nav' : 'Expand Nav'}
        </button>
      </div>
    </div>
  );
}

ReactDOM.render(<DemoShell />, document.getElementById('root'));
